1	// The home screen and the app's signature interaction: a blank page you can
2	// type on immediately. Swiping up slides the page off the top while a fresh
3	// blank page rides in from the bottom under the same finger — release past
4	// the threshold (or flick) commits it; the keyboard stays up so you can keep
5	// typing. Notes land in Feed via the desktop-compatible core.
6	//
7	// This is the middle screen in the pre-pager native-stack model: Menu sits
8	// behind it to the left, while Sync is pushed to the right. Native back
9	// reveals Menu; a leftward drag drives a live Sync preview before the real
10	// screen is attached underneath it.
11	//
12	//   swipe UP   → file the page. The pan uses manual activation gated on the
13	//                scroll geometry (shared values), so on a long note one
14	//                continuous drag scrolls to the bottom and rolls straight
15	//                into pulling the next page in; on a short note it claims
16	//                immediately. Works with the keyboard up — the fresh page
17	//                then enters from the keyboard's top edge.
18	//   swipe DOWN → the ScrollView's native interactive keyboardDismissMode
19	//                (drag toward/past the keyboard, Apple-Notes style), plus a
20	//                quick pull-down at the very top of the note. Both leave the
21	//                scroll untouched — the dismiss observer never activates.
22	//
23	// The TextInput no longer scrolls itself: an outer ScrollView owns scrolling
24	// (the input auto-grows), which is what makes interactive keyboard dismissal,
25	// UI-thread edge gating, and the custom barely-there scroll indicator
26	// possible. The page's bottom padding tracks the keyboard height so the text
27	// always sits above it, and content growth keeps the bottom pinned while
28	// you're typing at the end (scroll anchoring), like Apple Notes.
29	
30	import { Ionicons } from "@expo/vector-icons";
31	import { useNavigation } from "@react-navigation/native";
32	import type { NativeStackNavigationProp } from "@react-navigation/native-stack";
33	import { useEffect, useMemo, useRef, useState } from "react";
34	import {
35	  Keyboard,
36	  type LayoutChangeEvent,
37	  StyleSheet,
38	  Text,
39	  TextInput,
40	  useWindowDimensions,
41	  View,
42	} from "react-native";
43	import { Gesture, GestureDetector } from "react-native-gesture-handler";
44	import Animated, {
45	  Easing,
46	  runOnJS,
47	  runOnUI,
48	  scrollTo,
49	  useAnimatedKeyboard,
50	  useAnimatedRef,
51	  useAnimatedScrollHandler,
52	  useAnimatedStyle,
53	  useSharedValue,
54	  withDelay,
55	  withSpring,
56	  withTiming,
57	} from "react-native-reanimated";
58	import { useSafeAreaInsets } from "react-native-safe-area-context";
59	
60	import * as core from "@typenotes/mobile-core/core-api";
61	
62	import { CaptureSession } from "../lib/capture";
63	import { useClearInstantParam, type RootStackParamList } from "../navigation";
64	import { useNotesStore } from "../state/notes-store";
65	import { useTheme } from "../theme";
66	import { DictationButton } from "../ui/dictation-button";
67	import { ToolbarButton } from "../ui/toolbar-button";
68	
69	// Releasing past this fraction of the visible page height commits the swipe;
70	// a faster upward flick commits regardless of distance.
71	const COMMIT_FRACTION = 0.2;
72	const COMMIT_VELOCITY = -550;
73	// How far past the arm point (the bottom edge) the finger must travel before
74	// the pan claims the touch from the scroll — small enough to feel instant,
75	// big enough to ignore jitter.
76	const ACTIVATE_PULL = 6;
77	// Reserve the standard iOS back-swipe edge exclusively for native-stack
78	// navigation. Capture gestures do not even begin inside this gutter.
79	const BACK_SWIPE_GUTTER = 48;
80	// Outside the gutter, vertical observers still fail as soon as horizontal
81	// intent is clear so the navigator does not wait behind a BEGAN handler.
82	const HORIZONTAL_FAIL = 8;
83	// Scroll-edge slack (px): treat "within a few px" as at the edge.
84	const BOTTOM_SLACK = 6;
85	const TOP_SLACK = 4;
86	// Pull-down at the top of the note that tucks the keyboard away.
87	const ESCAPE_DRAG = 14;
88	
89	// Horizontal Capture -> Sync preview mechanics, matching Menu -> Capture.
90	const SYNC_OPEN_PROGRESS = 0.3;
91	const SYNC_OPEN_VELOCITY = -500;
92	const SYNC_PARALLAX = 0.3;
93	
94	const PLACEHOLDER = "Start typing…";
95	
96	const COMMIT_SPRING = {
97	  damping: 34,
98	  stiffness: 320,
99	  overshootClamping: true,
100	} as const;
101	const CANCEL_SPRING = {
102	  damping: 26,
103	  stiffness: 280,
104	  overshootClamping: true,
105	} as const;
106	
107	export const CaptureScreen = () => {
108	  const theme = useTheme();
109	  const insets = useSafeAreaInsets();
110	  const navigation =
111	    useNavigation<NativeStackNavigationProp<RootStackParamList>>();
112	  const { height, width } = useWindowDimensions();
113	
114	  const [text, setText] = useState("");
115	  const [iconsVisible, setIconsVisible] = useState(true);
116	  const [recordingActive, setRecordingActive] = useState(false);
117	  const iconsOpacity = useSharedValue(1);
118	  const inputRef = useRef<TextInput>(null);
119	  const scrollRef = useAnimatedRef<Animated.ScrollView>();
120	
121	  // The keyboard height (0 when hidden) as a UI-thread shared value; the page
122	  // padding and the floating controls ride it so nothing hides under the
123	  // keyboard, and it also defines the visible page height for the swipe.
124	  const keyboard = useAnimatedKeyboard();
125	
126	  // Live scroll geometry as shared values — the gestures and the custom
127	  // scroll indicator read these on the UI thread, so edge gating never waits
128	  // on the JS thread.
129	  const offsetY = useSharedValue(0);
130	  const viewportH = useSharedValue(0);
131	  const contentH = useSharedValue(0);
132	  // JS-side mirrors for the scroll-anchoring math in the content-size and
133	  // layout handlers (previous values, which the shared values no longer hold).
134	  const viewportHRef = useRef(0);
135	  const prevContentHRef = useRef(0);
136	
137	  // 0..-V — how far the current page has slid up (V = visible page height).
138	  const pageY = useSharedValue(0);
139	  // True from commit-release until the fresh page has swapped in.
140	  const transitioning = useSharedValue(false);
141	
142	  const indicatorOpacity = useSharedValue(0);
143	
144	  const session = useMemo(
145	    () =>
146	      new CaptureSession({
147	        createNote: async (content) => (await core.createNote({ content })).path,
148	        writeNote: core.writeNote,
149	        deleteNote: (path) => core.deleteItems([path]),
150	      }),
151	    []
152	  );
153	
154	  // Stack navigation emits blur for Menu, Sync, and all pushed destinations.
155	  // Flush before this capture screen becomes hidden or is popped.
156	  useEffect(
157	    () =>
158	      navigation.addListener("blur", () => {
159	        // Navigation should never turn a storage rejection into a fatal,
160	        // unhandled JS error. CaptureSession keeps the draft dirty for retry.
161	        void session.flush().catch(() => {});
162	      }),
163	    [navigation, session]
164	  );
165	
166	  // Menu's finger-driven preview can attach Capture with animation disabled;
167	  // clear that one-shot flag once mounted so later native back gestures work.
168	  useClearInstantParam();
169	
170	  // Wrap Keyboard.dismiss so the worklet captures this plain closure rather
171	  // than the bare method — passing Keyboard.dismiss straight to runOnJS makes
172	  // worklets try to copy its owner (KeyboardImpl), which it can't serialize.
173	  const dismissKeyboard = () => Keyboard.dismiss();
174	
175	  const showIcons = () => {
176	    setIconsVisible(true);
177	    iconsOpacity.value = withTiming(1, { duration: 180 });
178	  };
179	
180	  const hideIcons = () => {
181	    setIconsVisible(false);
182	    iconsOpacity.value = withTiming(0, { duration: 180 });
183	  };
184	
185	  // The committed page is off-screen (the ghost covers the viewport). Wait
186	  // for persistence before exposing the fresh page: this prevents new typing
187	  // from racing the old note's commit and lets a failed write spring the
188	  // original page back instead of losing it or surfacing a fatal rejection.
189	  const finishCommit = () => {
190	    void session
191	      .commit()
192	      .then((path) => {
193	        if (path) {
194	          void useNotesStore.getState().refresh().catch(() => {});
195	        }
196	        setText("");
197	        prevContentHRef.current = 0;
198	        runOnUI(() => {
199	          scrollTo(scrollRef, 0, 0, false);
200	        })();
201	        showIcons();
202	        requestAnimationFrame(() =>
203	          requestAnimationFrame(() => {
204	            pageY.value = 0;
205	            transitioning.value = false;
206	          })
207	        );
208	      })
209	      .catch(() => {
210	        transitioning.value = false;
211	        pageY.value = withSpring(0, CANCEL_SPRING);
212	      });
213	  };
214	
215	  // ---- Scroll plumbing ------------------------------------------------------
216	
217	  const onScroll = useAnimatedScrollHandler({
218	    onScroll: (event) => {
219	      offsetY.value = event.contentOffset.y;
220	      contentH.value = event.contentSize.height;
221	      viewportH.value = event.layoutMeasurement.height;
222	      // Surface the indicator while scrolling; let it fade shortly after.
223	      indicatorOpacity.value = 1;
224	      indicatorOpacity.value = withDelay(600, withTiming(0, { duration: 350 }));
225	    },
226	  });
227	
228	  // Scroll anchoring: when content grows while the view sits at (or near) the
229	  // bottom — typing at the end of the note — keep the bottom pinned so the
230	  // caret stays above the keyboard. Growth while reading higher up never
231	  // yanks the view down.
232	  const onContentSizeChange = (_width: number, contentHeight: number) => {
233	    const previous = prevContentHRef.current;
234	    prevContentHRef.current = contentHeight;
235	    contentH.value = contentHeight;
236	    const viewport = viewportHRef.current;
237	    if (viewport <= 0 || contentHeight <= viewport) {
238	      return;
239	    }
240	    const wasAtBottom =
241	      previous <= viewport || offsetY.value >= previous - viewport - 48;
242	    if (wasAtBottom) {
243	      runOnUI(() => {
244	        scrollTo(scrollRef, 0, contentHeight - viewport, false);
245	      })();
246	    }
247	  };
248	
249	  // The viewport shrinks/grows as the keyboard padding animates; keep the
250	  // bottom pinned through that too (only when it was pinned before).
251	  const onScrollViewLayout = (event: LayoutChangeEvent) => {
252	    const previous = viewportHRef.current;
253	    const viewport = event.nativeEvent.layout.height;
254	    viewportHRef.current = viewport;
255	    viewportH.value = viewport;
256	    const content = prevContentHRef.current;
257	    if (viewport < previous && content > viewport) {
258	      const wasAtBottom = offsetY.value >= content - previous - 48;
259	      if (wasAtBottom) {
260	        runOnUI(() => {
261	          scrollTo(scrollRef, 0, content - viewport, false);
262	        })();
263	      }
264	    }
265	  };
266	
267	  // ---- Gestures --------------------------------------------------------------
268	
269	  // Swipe up → file the page. Manual activation, gated on live scroll
270	  // geometry: the pan claims the touch only once the note sits at its bottom
271	  // edge and the finger keeps moving up — so a long note scrolls first and
272	  // the same drag rolls into the page pull the moment it hits the end. While
273	  // the note is above the bottom, the arm point trails the finger, so the
274	  // extra pull needed once the edge arrives is always the same few px.
275	  const touchStartX = useSharedValue(0);
276	  const touchStartY = useSharedValue(0);
277	  const armY = useSharedValue(0);
278	  const dragBase = useSharedValue(0);
279	
280	  const swipeToFile = Gesture.Pan()
281	    .hitSlop({ left: -BACK_SWIPE_GUTTER })
282	    .manualActivation(true)
283	    .onTouchesDown((event, manager) => {
284	      if (transitioning.value) {
285	        manager.fail();
286	        return;
287	      }
288	      const touch = event.allTouches[0];
289	      // iOS can deliver a terminal/cancel frame with no remaining touches.
290	      // Never dereference that sparse frame inside a worklet.
291	      if (!touch) {
292	        manager.fail();
293	        return;
294	      }
295	      touchStartX.value = touch.x;
296	      touchStartY.value = touch.y;
297	      armY.value = touch.y;
298	    })
299	    .onTouchesMove((event, manager) => {
300	      const touch = event.allTouches[0];
301	      if (!touch) {
302	        manager.fail();
303	        return;
304	      }
305	      const dx = touch.x - touchStartX.value;
306	      const dy = touch.y - touchStartY.value;
307	      // Clearly-horizontal drags belong to native back or the Sync push.
308	      if (Math.abs(dx) > HORIZONTAL_FAIL && Math.abs(dx) > Math.abs(dy)) {
309	        manager.fail();
310	        return;
311	      }
312	      const maxScroll = Math.max(0, contentH.value - viewportH.value);
313	      const atBottom = offsetY.value >= maxScroll - BOTTOM_SLACK;
314	      if (!atBottom) {
315	        // Still scrolling — keep the arm point under the finger.
316	        armY.value = touch.y;
317	        return;
318	      }
319	      if (armY.value - touch.y > ACTIVATE_PULL) {
320	        manager.activate();
321	      }
322	    })
323	    .onStart((event) => {
324	      // Translation accumulated before activation belongs to the scroll;
325	      // the page follows 1:1 from the claim point on.
326	      dragBase.value = event.translationY;
327	    })
328	    .onUpdate((event) => {
329	      const pull = -(event.translationY - dragBase.value);
330	      const pageHeight = Math.max(1, height - keyboard.height.value);
331	      pageY.value = -Math.min(Math.max(pull, 0), pageHeight);
332	    })
333	    .onEnd((event) => {
334	      const pageHeight = Math.max(1, height - keyboard.height.value);
335	      const shouldCommit =
336	        -pageY.value > pageHeight * COMMIT_FRACTION ||
337	        event.velocityY < COMMIT_VELOCITY;
338	      if (shouldCommit) {
339	        transitioning.value = true;
340	        pageY.value = withSpring(
341	          -pageHeight,
342	          { ...COMMIT_SPRING, velocity: event.velocityY },
343	          (finished) => {
344	            if (finished) {
345	              runOnJS(finishCommit)();
346	            } else {
347	              // Interrupted mid-flight (unmount, new gesture) — don't leave
348	              // the page stranded off-screen without a swap.
349	              transitioning.value = false;
350	              pageY.value = withSpring(0, CANCEL_SPRING);
351	            }
352	          }
353	        );
354	      } else {
355	        pageY.value = withSpring(0, {
356	          ...CANCEL_SPRING,
357	          velocity: event.velocityY,
358	        });
359	      }
360	    })
361	    .onFinalize(() => {
362	      // Cancellation without onEnd (system claimed the touch): spring home.
363	      if (!transitioning.value && pageY.value !== 0) {
364	        pageY.value = withSpring(0, CANCEL_SPRING);
365	      }
366	    });
367	
368	  // Quick pull-down at the very top of the note tucks the keyboard away.
369	  // This observer never activates — it dispatches the dismiss and fails, so
370	  // the note's own scroll (top bounce) keeps running untouched. Everywhere
371	  // else the ScrollView's interactive keyboardDismissMode covers it.
372	  const escapeStartX = useSharedValue(0);
373	  const escapeStartY = useSharedValue(0);
374	  const escapeDone = useSharedValue(false);
375	
376	  const keyboardEscape = Gesture.Pan()
377	    .hitSlop({ left: -BACK_SWIPE_GUTTER })
378	    .manualActivation(true)
379	    .onTouchesDown((event, manager) => {
380	      const touch = event.allTouches[0];
381	      if (!touch) {
382	        manager.fail();
383	        return;
384	      }
385	      escapeStartX.value = touch.x;
386	      escapeStartY.value = touch.y;
387	      escapeDone.value = false;
388	    })
389	    .onTouchesMove((event, manager) => {
390	      if (escapeDone.value) {
391	        return;
392	      }
393	      const touch = event.allTouches[0];
394	      if (!touch) {
395	        manager.fail();
396	        return;
397	      }
398	      const dx = touch.x - escapeStartX.value;
399	      const dy = touch.y - escapeStartY.value;
400	      if (Math.abs(dx) > HORIZONTAL_FAIL && Math.abs(dx) > Math.abs(dy)) {
401	        manager.fail();
402	        return;
403	      }
404	      if (dy < -10) {
405	        manager.fail();
406	        return;
407	      }
408	      if (
409	        keyboard.height.value > 60 &&
410	        offsetY.value <= TOP_SLACK &&
411	        dy > ESCAPE_DRAG
412	      ) {
413	        escapeDone.value = true;
414	        runOnJS(dismissKeyboard)();
415	        manager.fail();
416	      }
417	    });
418	
419	  // Sync sits to the right of Capture. A clearly-leftward drag pulls in a
420	  // lightweight replica of its native header, with the current page moving
421	  // in parallax underneath. Once committed, the real Sync screen is pushed
422	  // with animation disabled so there is no second transition.
423	  const syncProgress = useSharedValue(0);
424	
425	  const openSyncBehindPreview = () => {
426	    navigation.navigate("Sync", { instant: true });
427	    // `animation: none` has no reliable attached callback. Keep the preview
428	    // for long enough to cover the mount, then park it off-screen again.
429	    setTimeout(() => {
430	      syncProgress.value = 0;
431	    }, 400);
432	  };
433	
434	  const swipeToSync = Gesture.Pan()
435	    .hitSlop({ left: -BACK_SWIPE_GUTTER })
436	    .activeOffsetX(-24)
437	    .failOffsetX(HORIZONTAL_FAIL)
438	    .failOffsetY([-24, 24])
439	    .onStart(() => {
440	      runOnJS(dismissKeyboard)();
441	    })
442	    .onUpdate((event) => {
443	      syncProgress.value = Math.min(
444	        1,
445	        Math.max(0, -event.translationX / Math.max(width, 1))
446	      );
447	    })
448	    .onEnd((event) => {
449	      const shouldOpen =
450	        syncProgress.value > SYNC_OPEN_PROGRESS ||
451	        event.velocityX < SYNC_OPEN_VELOCITY;
452	      if (shouldOpen) {
453	        syncProgress.value = withTiming(
454	          1,
455	          { duration: 160, easing: Easing.out(Easing.cubic) },
456	          (finished) => {
457	            if (finished) {
458	              runOnJS(openSyncBehindPreview)();
459	            }
460	          }
461	        );
462	      } else {
463	        syncProgress.value = withTiming(0, { duration: 180 });
464	      }
465	    });
466	
467	  // ---- Animated styles --------------------------------------------------------
468	
469	  const syncDepthStyle = useAnimatedStyle(() => ({
470	    transform: [{ translateX: -width * SYNC_PARALLAX * syncProgress.value }],
471	  }));
472	  const syncDimStyle = useAnimatedStyle(() => ({
473	    opacity: 0.08 * syncProgress.value,
474	  }));
475	  const syncPreviewStyle = useAnimatedStyle(() => ({
476	    transform: [{ translateX: width * (1 - syncProgress.value) }],
477	    opacity: syncProgress.value > 0 ? 1 : 0,
478	  }));
479	
480	  // The page rides the swipe and its bottom padding tracks the keyboard so
481	  // the caret is never covered.
482	  const pageStyle = useAnimatedStyle(() => ({
483	    transform: [{ translateY: pageY.value }],
484	    paddingBottom: keyboard.height.value,
485	  }));
486	
487	  // The fresh page enters from the bottom of the *visible* area — with the
488	  // keyboard up that's the keyboard's top edge, so it never hides behind it.
489	  const ghostStyle = useAnimatedStyle(() => {
490	    const pageHeight = Math.max(1, height - keyboard.height.value);
491	    return {
492	      transform: [{ translateY: pageY.value + pageHeight }],
493	      paddingBottom: keyboard.height.value,
494	    };
495	  });
496	
497	  // Custom scroll indicator: a hair of a bar a few tints off the background,
498	  // visible only while scrolling. (The native one can't be styled on a
499	  // TextInput/ScrollView beyond black/white, so it's hidden and redrawn.)
500	  const indicatorStyle = useAnimatedStyle(() => {
501	    const track = viewportH.value;
502	    const content = Math.max(contentH.value, 1);
503	    if (content <= track + 8 || track <= 0) {
504	      return { opacity: 0, height: 0, transform: [{ translateY: 0 }] };
505	    }
506	    const barHeight = Math.min(track, Math.max(28, (track * track) / content));
507	    const progress = Math.min(Math.max(offsetY.value / (content - track), 0), 1);
508	    return {
509	      opacity: indicatorOpacity.value,
510	      height: barHeight,
511	      transform: [{ translateY: progress * (track - barHeight) }],
512	    };
513	  });
514	
515	  const toolbarStyle = useAnimatedStyle(() => ({
516	    opacity: iconsOpacity.value,
517	  }));
518	  // The dictation FAB floats close above the keyboard when it's up, and at
519	  // its resting spot above the home indicator when it's not.
520	  const fabStyle = useAnimatedStyle(() => ({
521	    opacity: iconsOpacity.value,
522	    transform: [
523	      {
524	        translateY: Math.min(
525	          0,
526	          insets.bottom + 36 - keyboard.height.value - 12
527	        ),
528	      },
529	    ],
530	  }));
531	
532	  const onChange = (value: string) => {
533	    setText(value);
534	    session.onChange(value);
535	    // Keep the page uncluttered while writing; tapping back into the text
536	    // brings the buttons back. While a dictation is running the stop button
537	    // must stay reachable, so nothing fades.
538	    if (iconsVisible && !recordingActive) {
539	      hideIcons();
540	    }
541	  };
542	
543	  // Dictation is the alternative to typing a page, so the mic only shows on
544	  // a blank page (or while a recording is running and must stay stoppable).
545	  const micAvailable = text.trim().length === 0 || recordingActive;
546	
547	  return (
548	    <View style={[styles.root, { backgroundColor: theme.colors.background }]}>
549	      <Animated.View style={[styles.depth, syncDepthStyle]}>
550	        <GestureDetector
551	          gesture={Gesture.Race(swipeToFile, keyboardEscape, swipeToSync)}
552	        >
553	          <View style={styles.gestureHost} collapsable={false}>
554	            <Animated.View
555	              style={[
556	                styles.page,
557	                {
558	                  backgroundColor: theme.colors.background,
559	                  paddingTop: insets.top + 12,
560	                },
561	                pageStyle,
562	              ]}
563	            >
564	              <Animated.ScrollView
565	                ref={scrollRef}
566	                style={styles.scroll}
567	                contentContainerStyle={styles.scrollContent}
568	                onScroll={onScroll}
569	                scrollEventThrottle={16}
570	                onContentSizeChange={onContentSizeChange}
571	                onLayout={onScrollViewLayout}
572	                keyboardDismissMode="interactive"
573	                keyboardShouldPersistTaps="handled"
574	                showsVerticalScrollIndicator={false}
575	                directionalLockEnabled
576	                alwaysBounceVertical
577	              >
578	                <TextInput
579	                  ref={inputRef}
580	                  style={[styles.input, { color: theme.colors.text }]}
581	                  value={text}
582	                  onChangeText={onChange}
583	                  onPressIn={showIcons}
584	                  placeholder={PLACEHOLDER}
585	                  placeholderTextColor={theme.colors.secondaryText}
586	                  multiline
587	                  scrollEnabled={false}
588	                  textAlignVertical="top"
589	                  keyboardAppearance={theme.dark ? "dark" : "light"}
590	                />
591	              </Animated.ScrollView>
592	              <View pointerEvents="none" style={styles.indicatorTrack}>
593	                <Animated.View
594	                  style={[
595	                    styles.indicator,
596	                    {
597	                      backgroundColor: theme.dark
598	                        ? "rgba(255,255,255,0.09)"
599	                        : "rgba(0,0,0,0.09)",
600	                    },
601	                    indicatorStyle,
602	                  ]}
603	                />
604	              </View>
605	            </Animated.View>
606	
607	            {/* The incoming blank page trails exactly one visible-page
608	                height below the current one. The real input is cleared only
609	                while this ghost fully covers it, avoiding a text flash. */}
610	            <Animated.View
611	              pointerEvents="none"
612	              style={[
613	                styles.ghost,
614	                {
615	                  backgroundColor: theme.colors.background,
616	                  borderTopColor: theme.colors.border,
617	                  paddingTop: insets.top + 12 + 44,
618	                },
619	                ghostStyle,
620	              ]}
621	            >
622	              <Text
623	                style={[
624	                  styles.ghostPlaceholder,
625	                  { color: theme.colors.secondaryText },
626	                ]}
627	              >
628	                {PLACEHOLDER}
629	              </Text>
630	            </Animated.View>
631	          </View>
632	        </GestureDetector>
633	
634	        <Animated.View
635	          pointerEvents={iconsVisible ? "auto" : "none"}
636	          style={[styles.toolbarLeft, { top: insets.top + 8 }, toolbarStyle]}
637	        >
638	          <ToolbarButton
639	            icon="menu-outline"
640	            // Menu is the root immediately beneath Capture. popTo avoids
641	            // accidentally pushing a duplicate Menu screen.
642	            onPress={() => navigation.popTo("Menu")}
643	          />
644	        </Animated.View>
645	        {micAvailable ? (
646	          <Animated.View
647	            pointerEvents={iconsVisible ? "auto" : "none"}
648	            style={[styles.fab, { bottom: insets.bottom + 36 }, fabStyle]}
649	          >
650	            <DictationButton onRecordingChange={setRecordingActive} />
651	          </Animated.View>
652	        ) : null}
653	      </Animated.View>
654	
655	      <Animated.View
656	        pointerEvents="none"
657	        style={[StyleSheet.absoluteFill, styles.syncDim, syncDimStyle]}
658	      />
659	      <Animated.View
660	        pointerEvents="none"
661	        style={[
662	          styles.syncPreview,
663	          { backgroundColor: theme.colors.background },
664	          syncPreviewStyle,
665	        ]}
666	      >
667	        <View style={{ paddingTop: insets.top }}>
668	          <View style={styles.syncPreviewBar}>
669	            <Ionicons
670	              name="chevron-back"
671	              size={26}
672	              color={theme.colors.text}
673	              style={styles.syncPreviewBack}
674	            />
675	            <Text style={[styles.syncPreviewTitle, { color: theme.colors.text }]}>
676	              Sync
677	            </Text>
678	          </View>
679	        </View>
680	      </Animated.View>
681	    </View>
682	  );
683	};
684	
685	const styles = StyleSheet.create({
686	  root: { flex: 1 },
687	  depth: { flex: 1 },
688	  syncDim: { backgroundColor: "#000" },
689	  syncPreview: {
690	    position: "absolute",
691	    top: 0,
692	    left: 0,
693	    right: 0,
694	    bottom: 0,
695	    shadowColor: "#000",
696	    shadowOffset: { width: -4, height: 0 },
697	    shadowOpacity: 0.12,
698	    shadowRadius: 10,
699	  },
700	  // Replica of the native-stack Sync header used only during the interactive
701	  // preview; the real screen takes over after the no-animation push.
702	  syncPreviewBar: { height: 44, alignItems: "center", justifyContent: "center" },
703	  syncPreviewBack: { position: "absolute", left: 8, top: 9 },
704	  syncPreviewTitle: { fontSize: 17, fontWeight: "600" },
705	  gestureHost: { flex: 1 },
706	  page: { flex: 1, paddingHorizontal: 20 },
707	  scroll: { flex: 1 },
708	  // flexGrow (not flex) so the input fills the viewport at minimum but the
709	  // container still grows with the input's content beyond it.
710	  scrollContent: { flexGrow: 1 },
711	  input: {
712	    flexGrow: 1,
713	    fontSize: 17,
714	    lineHeight: 26,
715	    paddingTop: 44,
716	    paddingBottom: 24,
717	  },
718	  // The custom scroll indicator's rail, pinned to the scroll area's right
719	  // edge (absolute children respect the page's animated bottom padding).
720	  indicatorTrack: {
721	    position: "absolute",
722	    top: 4,
723	    bottom: 4,
724	    right: 2,
725	    width: 3,
726	  },
727	  indicator: {
728	    width: 3,
729	    borderRadius: 2,
730	  },
731	  // The incoming page: full-screen, with a paper edge (hairline + soft
732	  // shadow) so it reads as a sheet sliding in on the same background.
733	  ghost: {
734	    position: "absolute",
735	    top: 0,
736	    left: 0,
737	    right: 0,
738	    bottom: 0,
739	    paddingHorizontal: 20,
740	    borderTopWidth: StyleSheet.hairlineWidth,
741	    shadowColor: "#000",
742	    shadowOffset: { width: 0, height: -2 },
743	    shadowOpacity: 0.05,
744	    shadowRadius: 12,
745	  },
746	  ghostPlaceholder: {
747	    fontSize: 17,
748	    lineHeight: 26,
749	  },
750	  fab: {
751	    position: "absolute",
752	    right: 32,
753	    alignItems: "flex-end",
754	  },
755	  toolbarLeft: {
756	    position: "absolute",
757	    left: 20,
758	    flexDirection: "row",
759	  },
760	});
