1	// In-memory RawCore implementation. Two consumers:
2	//
3	// 1. Tests — core-api and the app's stores run against it without native code.
4	// 2. Demo mode — when the generated turbo module isn't linked (Expo Go, CI,
5	//    simulators without a Rust toolchain), the app can boot against this and
6	//    stay fully interactive; the UI shows a "demo mode" banner.
7	//
8	// Behavior mirrors the Rust core where the UI can observe it (system folders,
9	// note lifecycle, pending → completed transcription statuses, the
10	// transcription_mode merge rule), but it is deliberately a toy: nothing
11	// persists, git operations only simulate success.
12	
13	import type { FolderNode, NoteMeta, ProfileSettings } from "@typenotes/shared/types";
14	
15	import type { RawCore, RawTranscriptionProvider } from "./raw-core";
16	
17	type MockNote = {
18	  content: string;
19	  meta: NoteMeta;
20	};
21	
22	const FEED = "Feed";
23	const ARCHIEVE = "Archieve"; // intentional typo, matches persisted data
24	const RECORDINGS = "Recordings"; // hidden storage folder
25	const ATTACHMENTS = "Attachments"; // hidden storage folder
26	
27	const defaultProfileSettings = (): ProfileSettings => ({
28	  git_remote_url: "",
29	  git_branch: "main",
30	  git_username: "",
31	  git_password: "",
32	  git_commit_message: "Sync notes",
33	  git_trusted_ssh_host: "",
34	  git_trusted_ssh_host_key_sha256: "",
35	  mobile_auto_transcription_enabled: true,
36	  mobile_auto_handwriting_ocr_enabled: true,
37	  transcription_mode: null,
38	});
39	
40	const defaultAppConfig = () => ({
41	  assemblyai_api_key: "",
42	  whisper_model: "large-v3",
43	  handwriting_ocr_provider: "local",
44	  local_ocr_model_path: "",
45	  openai_api_key: "",
46	  openai_model: "gpt-4.1-mini",
47	  huggingface_api_key: "",
48	  huggingface_model: "microsoft/trocr-base-handwritten",
49	  note_file_name_format: "utc_timestamp_slug",
50	});
51	
52	const parentOf = (path: string) => {
53	  const index = path.lastIndexOf("/");
54	  return index === -1 ? "" : path.slice(0, index);
55	};
56	
57	const nameOf = (path: string) => {
58	  const index = path.lastIndexOf("/");
59	  return index === -1 ? path : path.slice(index + 1);
60	};
61	
62	const timestampSlug = (ms: number) =>
63	  new Date(ms).toISOString().replace(/\.\d{3}Z$/, "Z").replace(/:/g, "-");
64	
65	export type MockCoreOptions = {
66	  /** Seed a few demo notes so the UI has content on first launch. */
67	  seed?: boolean;
68	  now?: () => number;
69	};
70	
71	export const createMockCore = (options: MockCoreOptions = {}): RawCore => {
72	  const now = options.now ?? Date.now;
73	
74	  let folders = new Set<string>([FEED, ARCHIEVE, RECORDINGS, ATTACHMENTS]);
75	  let notes = new Map<string, MockNote>();
76	  let audio = new Map<string, { base64: string; mimeType: string }>();
77	  let images = new Map<string, { base64: string; mimeType: string }>();
78	  let counter = 0;
79	
80	  let profileSettings = defaultProfileSettings();
81	  let appConfig = defaultAppConfig();
82	  let commits: { id: string; summary: string; authored_ms: number }[] = [];
83	  let sshPublicKey: string | null = null;
84	
85	  let security = {
86	    encryption_enabled: false,
87	    locked: false,
88	    auto_lock_on_background: false,
89	  };
90	  let unlockPassword = "";
91	  let panicPassword = "";
92	
93	  const newNote = (folder: string, content: string, ms: number, extra?: Partial<NoteMeta>) => {
94	    counter += 1;
95	    folders.add(folder);
96	    const path = `${folder}/${timestampSlug(ms)}-note-${counter}.md`;
97	    notes.set(path, {
98	      content,
99	      meta: { created_ms: ms, updated_ms: ms, ...extra },
100	    });
101	    return path;
102	  };
103	
104	  const seed = () => {
105	    if (!options.seed) {
106	      return;
107	    }
108	    const base = now();
109	    newNote(FEED, "Welcome to Type\n\nThis build is running the in-memory demo core — notes are not persisted.", base - 3 * 86_400_000);
110	    newNote(FEED, "Swipe up on this page to file it away and get a fresh blank page.", base - 86_400_000);
111	    newNote("Ideas", "Ship the mobile app.", base - 3_600_000);
112	  };
113	  seed();
114	
115	  const buildTree = (): FolderNode => {
116	    const children = new Map<string, FolderNode>();
117	    const ensureFolderNode = (path: string): FolderNode => {
118	      if (!path) {
119	        throw new Error("root is built separately");
120	      }
121	      const existing = children.get(path);
122	      if (existing) {
123	        return existing;
124	      }
125	      const node: FolderNode = { name: nameOf(path), path, children: [], notes: [] };
126	      children.set(path, node);
127	      const parent = parentOf(path);
128	      if (parent) {
129	        ensureFolderNode(parent).children.push(node);
130	      }
131	      return node;
132	    };
133	
134	    for (const folder of folders) {
135	      if (folder !== RECORDINGS && folder !== ATTACHMENTS) {
136	        ensureFolderNode(folder);
137	      }
138	    }
139	    for (const path of notes.keys()) {
140	      const parent = parentOf(path);
141	      if (parent === RECORDINGS) {
142	        continue;
143	      }
144	      ensureFolderNode(parent || FEED);
145	      children.get(parent || FEED)!.notes.push({ name: nameOf(path), path });
146	    }
147	
148	    const sortNode = (node: FolderNode) => {
149	      node.children.sort((a, b) => a.name.localeCompare(b.name));
150	      node.notes.sort((a, b) => a.name.localeCompare(b.name));
151	      node.children.forEach(sortNode);
152	    };
153	    const root: FolderNode = {
154	      name: "",
155	      path: "",
156	      children: [...children.values()].filter((node) => !parentOf(node.path)),
157	      notes: [],
158	    };
159	    sortNode(root);
160	    return root;
161	  };
162	
163	  const requireNote = (path: string): MockNote => {
164	    const note = notes.get(path);
165	    if (!note) {
166	      throw new Error(`Note not found: ${path}`);
167	    }
168	    return note;
169	  };
170	
171	  const gitStatus = () => ({
172	    git_available: true,
173	    repo_initialized: profileSettings.git_remote_url !== "",
174	    current_branch: profileSettings.git_branch || "main",
175	    remote_url: profileSettings.git_remote_url || null,
176	    has_uncommitted_changes: false,
177	    push_required: false,
178	    ahead: 0,
179	    behind: 0,
180	    notes_root: "/demo/default/notes",
181	  });
182	
183	  const profilesSnapshot = () =>
184	    JSON.stringify({
185	      active_profile_id: "default",
186	      profiles: [
187	        {
188	          id: "default",
189	          name: "Default",
190	          description: "",
191	          notes_root: "/demo/default/notes",
192	          settings: profileSettings,
193	        },
194	      ],
195	      app_config: appConfig,
196	    });
197	
198	  const securityStateJson = () => JSON.stringify(security);
199	
200	  const completeTranscriptions = async (
201	    transcribe: (audioPath: string) => Promise<string>
202	  ) => {
203	    let scanned = 0;
204	    let queued = 0;
205	    let skipped = 0;
206	    for (const [, note] of notes) {
207	      const status = note.meta.transcription_status;
208	      if (!note.meta.recording_audio_path || status === undefined) {
209	        continue;
210	      }
211	      scanned += 1;
212	      if (status === "completed") {
213	        skipped += 1;
214	        continue;
215	      }
216	      note.content = await transcribe(note.meta.recording_audio_path);
217	      note.meta.transcription_status = "completed";
218	      note.meta.transcription_updated_ms = now();
219	      note.meta.updated_ms = now();
220	      queued += 1;
221	    }
222	    return JSON.stringify({ scanned, queued, skipped, in_flight: 0 });
223	  };
224	
225	  return {
226	    initCore: () => {},
227	
228	    // ── Notes ──
229	    getTree: async () => JSON.stringify(buildTree()),
230	    readNote: async (path) => requireNote(path).content,
231	    createNote: async (argsJson) => {
232	      const args = JSON.parse(argsJson) as {
233	        folder_path?: string | null;
234	        content?: string | null;
235	        timestamp_ms?: number | null;
236	      };
237	      const path = newNote(
238	        args.folder_path || FEED,
239	        args.content ?? "",
240	        args.timestamp_ms ?? now()
241	      );
242	      return JSON.stringify({ path });
243	    },
244	    writeNote: async (path, content) => {
245	      const note = requireNote(path);
246	      note.content = content;
247	      note.meta.updated_ms = now();
248	    },
249	    setNoteTimestamp: async (argsJson) => {
250	      const args = JSON.parse(argsJson) as { path: string; timestamp_ms: number };
251	      requireNote(args.path).meta.created_ms = args.timestamp_ms;
252	    },
253	    updateNoteMarkers: async (argsJson) => {
254	      const args = JSON.parse(argsJson) as {
255	        path: string;
256	        archived?: boolean | null;
257	        reviewed?: boolean | null;
258	      };
259	      const meta = requireNote(args.path).meta;
260	      if (args.archived !== undefined && args.archived !== null) {
261	        meta.archived_ms = args.archived ? now() : null;
262	      }
263	      if (args.reviewed !== undefined && args.reviewed !== null) {
264	        meta.reviewed_ms = args.reviewed ? now() : null;
265	      }
266	    },
267	    getNoteMeta: async (path) => JSON.stringify(requireNote(path).meta),
268	    listNotePreviews: async (paths) =>
269	      JSON.stringify(
270	        paths
271	          .filter((path) => notes.has(path))
272	          .map((path) => ({
273	            path,
274	            content: notes.get(path)!.content,
275	            meta: notes.get(path)!.meta,
276	          }))
277	      ),
278	    moveItems: async (items, destination) => {
279	      folders.add(destination);
280	      for (const item of items) {
281	        if (notes.has(item)) {
282	          const note = notes.get(item)!;
283	          notes.delete(item);
284	          notes.set(`${destination}/${nameOf(item)}`, note);
285	          continue;
286	        }
287	        const moved = `${destination}/${nameOf(item)}`;
288	        for (const folder of [...folders]) {
289	          if (folder === item || folder.startsWith(`${item}/`)) {
290	            folders.delete(folder);
291	            folders.add(moved + folder.slice(item.length));
292	          }
293	        }
294	        for (const [path, note] of [...notes]) {
295	          if (path.startsWith(`${item}/`)) {
296	            notes.delete(path);
297	            notes.set(moved + path.slice(item.length), note);
298	          }
299	        }
300	      }
301	    },
302	    deleteItems: async (items) => {
303	      for (const item of items) {
304	        notes.delete(item);
305	        for (const folder of [...folders]) {
306	          if (folder === item || folder.startsWith(`${item}/`)) {
307	            folders.delete(folder);
308	          }
309	        }
310	        for (const path of [...notes.keys()]) {
311	          if (path.startsWith(`${item}/`)) {
312	            notes.delete(path);
313	          }
314	        }
315	      }
316	    },
317	    renameItem: async (path, newName) => {
318	      const parent = parentOf(path);
319	      const renamed = parent ? `${parent}/${newName}` : newName;
320	      if (notes.has(path)) {
321	        const note = notes.get(path)!;
322	        notes.delete(path);
323	        notes.set(renamed, note);
324	        return renamed;
325	      }
326	      for (const folder of [...folders]) {
327	        if (folder === path || folder.startsWith(`${path}/`)) {
328	          folders.delete(folder);
329	          folders.add(renamed + folder.slice(path.length));
330	        }
331	      }
332	      for (const [notePath, note] of [...notes]) {
333	        if (notePath.startsWith(`${path}/`)) {
334	          notes.delete(notePath);
335	          notes.set(renamed + notePath.slice(path.length), note);
336	        }
337	      }
338	      return renamed;
339	    },
340	    setOrder: async () => {},
341	
342	    // ── Working folders ──
343	    getProfiles: async () => profilesSnapshot(),
344	    createProfile: async () => profilesSnapshot(),
345	    setActiveProfile: async () => profilesSnapshot(),
346	    setProfileNotesRoot: async () => profilesSnapshot(),
347	    updateProfile: async () => profilesSnapshot(),
348	    deleteProfile: async () => {
349	      throw new Error("Demo mode: the default working folder cannot be deleted.");
350	    },
351	    updateProfileSettings: async (argsJson) => {
352	      const args = JSON.parse(argsJson) as { settings: ProfileSettings };
353	      const incoming = { ...args.settings };
354	      // Mirror the core's merge rule: a writer that doesn't set a mode must
355	      // not clear one that is already persisted.
356	      if (incoming.transcription_mode === undefined || incoming.transcription_mode === null) {
357	        incoming.transcription_mode = profileSettings.transcription_mode;
358	      }
359	      profileSettings = incoming;
360	      return profilesSnapshot();
361	    },
362	    updateAppConfig: async (argsJson) => {
363	      const args = JSON.parse(argsJson) as { config: typeof appConfig };
364	      appConfig = args.config;
365	      return profilesSnapshot();
366	    },
367	    createProfilesBackupZip: async () => {
368	      throw new Error("Demo mode: backups need the native core.");
369	    },
370	    exportProfilesToDocuments: async () => {
371	      throw new Error("Demo mode: exports need the native core.");
372	    },
373	
374	    // ── Git sync ──
375	    generateSshKey: async () => {
376	      sshPublicKey = "ssh-ed25519 AAAADEMOKEYnotesmobile demo@typenotes";
377	      return sshPublicKey;
378	    },
379	    getSshPublicKey: async () => sshPublicKey ?? undefined,
380	    deleteSshKey: async () => {
381	      sshPublicKey = null;
382	    },
383	    getGitStatus: async () => JSON.stringify(gitStatus()),
384	    getGitHistory: async () =>
385	      JSON.stringify(
386	        commits
387	          .slice()
388	          .reverse()
389	          .map((commit, index) => ({
390	            id: commit.id,
391	            short_id: commit.id.slice(0, 7),
392	            summary: commit.summary,
393	            author: "Demo",
394	            authored_ms: commit.authored_ms,
395	            sync_state: "synced",
396	            is_head: index === 0,
397	          }))
398	      ),
399	    connectGitRepo: async (argsJson) => {
400	      const args = JSON.parse(argsJson) as { remote_url?: string | null; branch?: string | null };
401	      profileSettings.git_remote_url = args.remote_url ?? profileSettings.git_remote_url;
402	      profileSettings.git_branch = args.branch ?? profileSettings.git_branch;
403	      return JSON.stringify(gitStatus());
404	    },
405	    gitPull: async () => JSON.stringify(gitStatus()),
406	    getGitSyncProgress: () =>
407	      JSON.stringify({
408	        phase: "idle",
409	        objects_done: 0,
410	        objects_total: 0,
411	        bytes: 0,
412	        remote_text: "",
413	      }),
414	    gitPush: async (argsJson) => {
415	      const args = JSON.parse(argsJson) as { message?: string | null };
416	      counter += 1;
417	      commits.push({
418	        id: `${counter}`.padStart(40, "0"),
419	        summary: args.message || profileSettings.git_commit_message,
420	        authored_ms: now(),
421	      });
422	      return JSON.stringify(gitStatus());
423	    },
424	
425	    // ── Recordings ──
426	    saveAudioRecording: async (argsJson) => {
427	      const args = JSON.parse(argsJson) as {
428	        audio_base64: string;
429	        mime_type?: string | null;
430	        folder_path?: string | null;
431	      };
432	      counter += 1;
433	      const audioPath = `${RECORDINGS}/audio-${counter}.m4a`;
434	      audio.set(audioPath, {
435	        base64: args.audio_base64,
436	        mimeType: args.mime_type ?? "audio/mp4",
437	      });
438	      const notePath = newNote(args.folder_path || FEED, "", now(), {
439	        note_type: "audio_recording",
440	        recording_audio_path: audioPath,
441	        transcription_status: "pending",
442	        transcription_updated_ms: now(),
443	      });
444	      return JSON.stringify({
445	        folder_path: args.folder_path || FEED,
446	        note_path: notePath,
447	        audio_path: audioPath,
448	      });
449	    },
450	    queueRecordingTranscriptions: async () =>
451	      completeTranscriptions(async () => "(demo transcript)"),
452	    queueProviderTranscriptions: async (provider: RawTranscriptionProvider) =>
453	      completeTranscriptions((audioPath) => Promise.resolve(provider.transcribe(audioPath))),
454	    listRecordings: async () =>
455	      JSON.stringify({
456	        queue: {
457	          running: false,
458	          current_recording: null,
459	          pending: [],
460	          in_flight: 0,
461	          progress: null,
462	        },
463	        recordings: [...notes.entries()]
464	          .filter(([, note]) => note.meta.recording_audio_path)
465	          .map(([path, note]) => ({
466	            note_path: path,
467	            folder_path: parentOf(path),
468	            audio_path: note.meta.recording_audio_path ?? null,
469	            status: note.meta.transcription_status ?? "pending",
470	            error: note.meta.transcription_error ?? null,
471	            updated_ms: note.meta.updated_ms,
472	            is_queued: false,
473	            is_processing: false,
474	          })),
475	      }),
476	    readRecordingAudio: async (path) => {
477	      const payload = audio.get(path);
478	      if (!payload) {
479	        throw new Error(`Audio not found: ${path}`);
480	      }
481	      return JSON.stringify({
482	        mime_type: payload.mimeType,
483	        audio_base64: payload.base64,
484	      });
485	    },
486	
487	    // ── Photo attachments ──
488	    saveHandwritingAttachment: async (argsJson) => {
489	      const args = JSON.parse(argsJson) as {
490	        image_base64: string;
491	        mime_type?: string | null;
492	        folder_path?: string | null;
493	      };
494	      counter += 1;
495	      const attachmentPath = `${ATTACHMENTS}/attachment-${counter}.jpg`;
496	      images.set(attachmentPath, {
497	        base64: args.image_base64,
498	        mimeType: args.mime_type ?? "image/jpeg",
499	      });
500	      const folder = args.folder_path || FEED;
501	      const notePath = newNote(folder, "", now(), {
502	        note_type: "handwriting_attachment",
503	        handwriting_attachment_path: attachmentPath,
504	        ocr_status: "pending",
505	        ocr_updated_ms: now(),
506	      });
507	      return JSON.stringify({
508	        folder_path: folder,
509	        note_path: notePath,
510	        attachment_path: attachmentPath,
511	      });
512	    },
513	
514	    // ── Security ──
515	    getSecurityState: async () => securityStateJson(),
516	    enableSecurity: async (argsJson) => {
517	      const args = JSON.parse(argsJson) as {
518	        unlock_password: string;
519	        panic_password: string;
520	      };
521	      security.encryption_enabled = true;
522	      unlockPassword = args.unlock_password;
523	      panicPassword = args.panic_password;
524	      return securityStateJson();
525	    },
526	    lockSecurity: async () => {
527	      if (security.encryption_enabled) {
528	        security.locked = true;
529	      }
530	      return securityStateJson();
531	    },
532	    unlockSecurity: async (argsJson) => {
533	      const args = JSON.parse(argsJson) as { password: string };
534	      if (security.encryption_enabled && args.password === panicPassword) {
535	        // Panic wipe: reset everything and reseed, like the real core.
536	        folders = new Set([FEED, ARCHIEVE, RECORDINGS, ATTACHMENTS]);
537	        notes = new Map();
538	        audio = new Map();
539	        images = new Map();
540	        commits = [];
541	        profileSettings = defaultProfileSettings();
542	        appConfig = defaultAppConfig();
543	        security = {
544	          encryption_enabled: false,
545	          locked: false,
546	          auto_lock_on_background: false,
547	        };
548	        unlockPassword = "";
549	        panicPassword = "";
550	        seed();
551	        return JSON.stringify({
552	          unlocked: false,
553	          panic_triggered: true,
554	          reset_required: true,
555	          message: null,
556	        });
557	      }
558	      const unlocked = !security.encryption_enabled || args.password === unlockPassword;
559	      if (unlocked) {
560	        security.locked = false;
561	      }
562	      return JSON.stringify({
563	        unlocked,
564	        panic_triggered: false,
565	        reset_required: false,
566	        message: unlocked ? null : "Invalid password.",
567	      });
568	    },
569	    setSecurityPreferences: async (argsJson) => {
570	      const args = JSON.parse(argsJson) as { auto_lock_on_background: boolean };
571	      security.auto_lock_on_background = args.auto_lock_on_background;
572	      return securityStateJson();
573	    },
574	  };
575	};
