1	// The floating dictation button (bottom-right of the capture page) — this
2	// replaced the old Record screen. Tap to start, tap again to stop. Long press
3	// reveals camera/gallery actions for handwriting
4	// photos. Saving goes through the core (Feed note + audio/image file +
5	// transcription_status: pending), then queues transcription according to the
6	// working folder's transcription_mode:
7	//
8	//   assemblyai → cloud queue now, on this device
9	//   native     → on-device speech recognition via the expo-speech-recognition
10	//                provider (lib/native-transcription), run by the core's queue
11	//   desktop    → stays pending; a synced desktop picks it up (local Whisper)
12	//   off        → stays pending until triggered manually
13	
14	import { Ionicons } from "@expo/vector-icons";
15	import {
16	  AudioModule,
17	  RecordingPresets,
18	  setAudioModeAsync,
19	  useAudioRecorder,
20	  useAudioRecorderState,
21	} from "expo-audio";
22	import * as FileSystem from "expo-file-system/legacy";
23	import * as ImagePicker from "expo-image-picker";
24	import { useEffect, useRef, useState } from "react";
25	import { Pressable, StyleSheet, Text, View } from "react-native";
26	
27	import * as core from "@typenotes/mobile-core/core-api";
28	import { getErrorMessage } from "@typenotes/shared/errors";
29	import {
30	  effectiveTranscriptionMode,
31	  type TranscriptionMode,
32	} from "@typenotes/shared/types";
33	
34	import { nativeTranscriptionProvider } from "../lib/native-transcription";
35	import { useNotesStore } from "../state/notes-store";
36	import { activeProfile, useSettingsStore } from "../state/settings-store";
37	import { useTheme } from "../theme";
38	
39	const STATUS_VISIBLE_MS = 4000;
40	
41	const MODE_SAVED_DETAIL: Record<TranscriptionMode, string> = {
42	  assemblyai: "Saved — transcribing via AssemblyAI",
43	  native: "Saved — transcribing on this device",
44	  desktop: "Saved — your desktop will transcribe it",
45	  off: "Saved",
46	};
47	
48	type PillStatus = { kind: "success" | "error"; text: string };
49	
50	export const DictationButton = ({
51	  onRecordingChange,
52	}: {
53	  onRecordingChange?: (recording: boolean) => void;
54	}) => {
55	  const theme = useTheme();
56	  const recorder = useAudioRecorder(RecordingPresets.HIGH_QUALITY);
57	  const recorderState = useAudioRecorderState(recorder);
58	
59	  const [busy, setBusy] = useState(false);
60	  const [status, setStatus] = useState<PillStatus | null>(null);
61	  const [attachmentMenuOpen, setAttachmentMenuOpen] = useState(false);
62	  const statusTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
63	
64	  // Start is async (permission prompt, prepare) — a hold can end before it
65	  // finishes, so stopAndSave awaits the in-flight start before stopping.
66	  const startPromise = useRef<Promise<void> | null>(null);
67	  const suppressNextPress = useRef(false);
68	
69	  const snapshot = useSettingsStore((s) => s.snapshot);
70	  const settings = activeProfile(snapshot)?.settings;
71	  const mode: TranscriptionMode = settings
72	    ? effectiveTranscriptionMode(settings)
73	    : "desktop";
74	
75	  useEffect(() => {
76	    onRecordingChange?.(recorderState.isRecording);
77	  }, [recorderState.isRecording, onRecordingChange]);
78	
79	  const showStatus = (next: PillStatus) => {
80	    if (statusTimer.current) {
81	      clearTimeout(statusTimer.current);
82	    }
83	    setStatus(next);
84	    statusTimer.current = setTimeout(() => setStatus(null), STATUS_VISIBLE_MS);
85	  };
86	  useEffect(
87	    () => () => {
88	      if (statusTimer.current) {
89	        clearTimeout(statusTimer.current);
90	      }
91	    },
92	    []
93	  );
94	
95	  const start = async () => {
96	    const permission = await AudioModule.requestRecordingPermissionsAsync();
97	    if (!permission.granted) {
98	      throw new Error("Microphone permission denied — enable it in system settings.");
99	    }
100	    await setAudioModeAsync({ allowsRecording: true, playsInSilentMode: true });
101	    await recorder.prepareToRecordAsync();
102	    recorder.record();
103	  };
104	
105	  const stopAndSave = async () => {
106	    setBusy(true);
107	    try {
108	      await startPromise.current;
109	      await recorder.stop();
110	      const uri = recorder.uri;
111	      if (!uri) {
112	        throw new Error("Recorder produced no file.");
113	      }
114	      const audioBase64 = await FileSystem.readAsStringAsync(uri, {
115	        encoding: "base64",
116	      });
117	      await core.saveAudioRecording({
118	        audio_base64: audioBase64,
119	        mime_type: "audio/mp4",
120	      });
121	
122	      let detail = MODE_SAVED_DETAIL[mode];
123	      if (mode === "assemblyai") {
124	        try {
125	          await core.queueRecordingTranscriptions();
126	        } catch (queueError) {
127	          detail = `Saved, but queueing failed: ${getErrorMessage(queueError)}`;
128	        }
