1	//! Note tree + CRUD, mirroring the desktop `commands/notes.rs` surface.
2	
3	use type_core::{
4	    application::notes::NotesService, notes_root, CreateNoteArgs, FilesystemNotesRepository,
5	    FrontMatterNoteDocumentCodec, RuntimeNoteBodyCrypto, SetNoteMarkersArgs, SetNoteTimestampArgs,
6	    SetOrderArgs, SystemNoteClock, UuidNoteIdGenerator,
7	};
8	
9	use crate::{from_json, run_blocking, to_json, unlocked_env, CoreError};
10	
11	fn notes_service() -> Result<
12	    NotesService<
13	        FilesystemNotesRepository,
14	        FrontMatterNoteDocumentCodec,
15	        RuntimeNoteBodyCrypto,
16	        UuidNoteIdGenerator,
17	        SystemNoteClock,
18	    >,
19	    String,
20	> {
21	    let root = notes_root(&unlocked_env()?)?;
22	    Ok(NotesService::new(
23	        FilesystemNotesRepository::new(root),
24	        FrontMatterNoteDocumentCodec,
25	        RuntimeNoteBodyCrypto,
26	        UuidNoteIdGenerator,
27	        SystemNoteClock,
28	    ))
29	}
30	
31	/// Folder tree as JSON (`FolderNode`).
32	#[uniffi::export(async_runtime = "tokio")]
33	pub async fn get_tree() -> Result<String, CoreError> {
34	    run_blocking(|| to_json(&notes_service()?.get_tree()?)).await
35	}
36	
37	/// Note body (decrypted when encryption is enabled).
38	#[uniffi::export(async_runtime = "tokio")]
39	pub async fn read_note(path: String) -> Result<String, CoreError> {
40	    run_blocking(move || notes_service()?.read_note(&path)).await
41	}
42	
43	/// `args_json`: `CreateNoteArgs`. Returns JSON `CreateNoteResult`.
44	#[uniffi::export(async_runtime = "tokio")]
45	pub async fn create_note(args_json: String) -> Result<String, CoreError> {
46	    run_blocking(move || {
47	        let args: CreateNoteArgs = from_json(&args_json)?;
48	        to_json(&notes_service()?.create_note(args)?)
49	    })
50	    .await
51	}
52	
53	#[uniffi::export(async_runtime = "tokio")]
54	pub async fn write_note(path: String, content: String) -> Result<(), CoreError> {
55	    run_blocking(move || notes_service()?.write_note(&path, &content)).await
56	}
57	
58	/// `args_json`: `SetNoteTimestampArgs`.
59	#[uniffi::export(async_runtime = "tokio")]
60	pub async fn set_note_timestamp(args_json: String) -> Result<(), CoreError> {
61	    run_blocking(move || {
62	        let args: SetNoteTimestampArgs = from_json(&args_json)?;
63	        notes_service()?.set_note_timestamp(args)
64	    })
65	    .await
66	}
67	
